function migrateNutritionData(){(data.consultations||[]).forEach(c=>{if(c.foodPlan)Object.values(c.foodPlan).flat().forEach(x=>{if(x.kcal==null){let f=FOOD_DB.find(z=>z[0]===x.name);if(f){x.cat=f[1];x.serving=f[3];x.kcal=Number(f[2])*Number(f[3])/100}else{x.kcal=0}}})});(data.patients||[]).forEach(p=>{if(!p.sex)p.sex="M"});save()}
